head.script:
/* ★Wcraft guide★ 스크립트 수작업 유의사항 */
/** * @method * @name fn_CalcPayDtCapAmt * @description desc * @param * @returns * @hidden N * @exception * @example */ scwin.fn_CalcPayDtCapAmt = function() { form["billPrsntsubmitddCap"].setValue(fn_SetComma(fn_RmComma(form["billPrsntsubmitddCmstkCap"].getValue()) + fn_RmComma(form["billPrsntsubmitddPrefstkCap"].getValue()))); }; /** * @method * @name fn_CalcPubSum * @description desc * @param * @returns * @hidden N * @exception * @example */ scwin.fn_CalcPubSum = function() { var invstgClmTpCd = form["invstgClmTpCd"].getValue(); if (invstgClmTpCd != 5) { var calc1 = eval(fn_RmComma(form["pubofrSchdlShrs"].getValue()) * fn_RmComma(form["pershrPubprcLwlmtAmt"].getValue())); var calc2 = eval(fn_RmComma(form["pubofrSchdlShrs"].getValue()) * fn_RmComma(form["pershrPubprcUplmtAmt"].getValue())); var calc3 = 0; if (form["listSchdlCmstkShrs"].getValue().length > 0 && form["listSchdlCmstkShrs"].getValue() != 0) { calc3 = eval(fn_RmComma(form["pubofrSchdlShrs"].getValue()) / fn_RmComma(form["listSchdlCmstkShrs"].getValue())); } form["lwlmtPubofrSchdlTotamt"].setValue(fn_SetComma(calc1)); form["uplmtPubofrSchdlTotamt"].setValue(fn_SetComma(calc2)); form["pubofrRto"].setValue((Math.round(calc3 * 10000) / 100)); } }; /** * @method * @name fn_CommaValueAll * @description desc * @param * @returns * @hidden N * @exception * @example */ scwin.fn_CommaValueAll = function() { fn_ObjValueSetComma(form["parval"]); // 액면가 fn_ObjValueSetComma(form["billPrsntsubmitddCap"]); // 청구서제출일현재자본금 fn_ObjValueSetComma(form["billPrsntsubmitddPrefstkCap"]); // 청구서제출일현재우선주자본금 fn_ObjValueSetComma(form["billPrsntsubmitddCmstkCap"]); // 청구서제출일현재보통주자본금 fn_ObjValueSetComma(form["prsntCmstkShrs"]); // 현재보통주주식수 fn_ObjValueSetComma(form["prsntPrefstkShrs"]); // 현재우선주주식수 fn_ObjValueSetComma(form["pubofrSchdlShrs"]); // 공모예정주식수 fn_ObjValueSetComma(form["listSchdlCmstkShrs"]); // 상장예정보통주주식수 fn_ObjValueSetComma(form["addAssgnOptShrs"]); // 추가배정옵션주식수 fn_ObjValueSetComma(form["listSchdlPrefstkShrs"]); // 상장예정우선주주식수 fn_ObjValueSetComma(form["pershrPubprcUplmtAmt"]); // 주당공모가상한금액 fn_ObjValueSetComma(form["pershrPubprcLwlmtAmt"]); // 주당공모가하한금액 fn_ObjValueSetComma(form["uplmtPubofrSchdlTotamt"]); // 상한공모예정총액 fn_ObjValueSetComma(form["lwlmtPubofrSchdlTotamt"]); // 하한공모예정총액 fn_ObjValueSetComma(form["pubofrRto"]); // 공모비율 fn_ObjValueSetComma(form["perBasVal"]); // 주가수익률기준가치 fn_ObjValueSetComma(form["pbrBasVal"]); // PBR기준가치 fn_ObjValueSetComma(form["evebitdaBasVal"]); // EV/EBITDA기준가치 fn_ObjValueSetComma(form["intrvalAmt"]); // 본질가치금액 fn_ObjValueSetComma(form["asstvalAmt"]); // 자산가치금액 fn_ObjValueSetComma(form["earngvalAmt"]); // 수익가치금액 fn_ObjValueSetComma(form["relvalAmt"]); // 상대가치금액 fn_ObjValueSetComma(form["bztpVal"]); // 사업성가치 fn_ObjValueSetComma(form["basPrc"]); // 기준가액 fn_ObjValueSetComma(form["anlVal1"]); // 분석가치1 fn_ObjValueSetComma(form["anlVal2"]); // 분석가치2 fn_ObjValueSetComma(form["anlVal3"]); // 분석가치3 fn_ObjValueSetComma(form["anlVal4"]); // 분석가치4
}; /** * @method * @name fn_RmCommaValueAll * @description desc * @param * @returns * @hidden N * @exception * @example */ scwin.fn_RmCommaValueAll = function() { fn_ObjValueResetRmComma2(form["parval"]); // 액면가 fn_ObjValueResetRmComma2(form["billPrsntsubmitddCap"]); // 청구서제출일현재자본금 fn_ObjValueResetRmComma2(form["billPrsntsubmitddPrefstkCap"]); // 청구서제출일현재우선주자본금 fn_ObjValueResetRmComma2(form["billPrsntsubmitddCmstkCap"]); // 청구서제출일현재보통주자본금 fn_ObjValueResetRmComma2(form["prsntCmstkShrs"]); // 현재보통주주식수 fn_ObjValueResetRmComma2(form["prsntPrefstkShrs"]); // 현재우선주주식수 fn_ObjValueResetRmComma2(form["pubofrSchdlShrs"]); // 공모예정주식수 fn_ObjValueResetRmComma2(form["listSchdlCmstkShrs"]); // 상장예정보통주주식수 fn_ObjValueResetRmComma2(form["addAssgnOptShrs"]); // 추가배정옵션주식수 fn_ObjValueResetRmComma2(form["listSchdlPrefstkShrs"]); // 상장예정우선주주식수 fn_ObjValueResetRmComma2(form["pershrPubprcUplmtAmt"]); // 주당공모가상한금액 fn_ObjValueResetRmComma2(form["pershrPubprcLwlmtAmt"]); // 주당공모가하한금액 fn_ObjValueResetRmComma2(form["uplmtPubofrSchdlTotamt"]); // 상한공모예정총액 fn_ObjValueResetRmComma2(form["lwlmtPubofrSchdlTotamt"]); // 하한공모예정총액 fn_ObjValueResetRmComma2(form["pubofrRto"]); // 공모비율 fn_ObjValueResetRmComma2(form["perBasVal"]); // 주가수익률기준가치 fn_ObjValueResetRmComma2(form["pbrBasVal"]); // PBR기준가치 fn_ObjValueResetRmComma2(form["evebitdaBasVal"]); // EV/EBITDA기준가치 fn_ObjValueResetRmComma2(form["intrvalAmt"]); // 본질가치금액 fn_ObjValueResetRmComma2(form["asstvalAmt"]); // 자산가치금액 fn_ObjValueResetRmComma2(form["earngvalAmt"]); // 수익가치금액 fn_ObjValueResetRmComma2(form["relvalAmt"]); // 상대가치금액 fn_ObjValueResetRmComma2(form["bztpVal"]); // 사업성가치 fn_ObjValueResetRmComma2(form["basPrc"]); // 기준가액 fn_ObjValueResetRmComma2(form["anlVal1"]); // 분석가치1 fn_ObjValueResetRmComma2(form["anlVal2"]); // 분석가치2 fn_ObjValueResetRmComma2(form["anlVal3"]); // 분석가치3 fn_ObjValueResetRmComma2(form["anlVal4"]); // 분석가치4
};
